import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第十七卦 隨 澤雷隨 兌上震下","description":"周易 - 第十七卦 隨 澤雷隨 兌上震下","frontmatter":{"title":"第十七卦 隨 澤雷隨 兌上震下","description":"周易 - 第十七卦 隨 澤雷隨 兌上震下"},"headers":[],"relativePath":"classics/zhouyi/018.md","filePath":"classics/zhouyi/018.md"}'),l={name:"classics/zhouyi/018.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="隨" tabindex="-1">隨 <a class="header-anchor" href="#隨" aria-label="Permalink to “隨”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元亨利貞，無咎。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>隨，剛來而下柔，動而說，隨。大亨貞，無咎，而天下隨時，隨之時義大矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>澤中有雷，隨；君子以嚮晦入宴息。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>官有渝，貞吉。出門交有功。象曰：官有渝，從正吉也。出門交有功，不失也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>系小子，失丈夫。象曰：系小子，弗兼與也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>系丈夫，失小子。隨有求得，利居貞。象曰：系丈夫，志舍下也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>隨有獲，貞兇。有孚在道，以明，何咎。象曰：隨有獲，其義兇也。有孚在道，明功也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>孚於嘉，吉。象曰：孚於嘉，吉；位正中也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>拘繫之，乃從維之。王用亨於西山。象曰：拘繫之，上窮也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
